<?php
require 'config.php';
require 'protecao.php';
require 'campanha_lib.php';
if(!defined('TENANT_ID')) die('Tenant não identificado.');
$tenantId=(int)TENANT_ID; $msg='';
function ap_h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function ap_pdf($campo,$tenantId){
    if(empty($_FILES[$campo]) || ($_FILES[$campo]['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE) return null;
    if($_FILES[$campo]['error']!==UPLOAD_ERR_OK) throw new Exception('Erro ao enviar o PDF.');
    if((int)$_FILES[$campo]['size']>15*1024*1024) throw new Exception('O PDF deve ter no máximo 15 MB.');
    $tmp=$_FILES[$campo]['tmp_name'];
    if(function_exists('finfo_open')){$f=finfo_open(FILEINFO_MIME_TYPE);$mime=$f?finfo_file($f,$tmp):'';if($f)finfo_close($f);if($mime!==''&&$mime!=='application/pdf')throw new Exception('Envie um PDF válido.');}
    $fp=@fopen($tmp,'rb');$sig=$fp?fread($fp,4):'';if($fp)fclose($fp);if($sig!=='%PDF')throw new Exception('O arquivo não é um PDF válido.');
    $rel='uploads/campanha/projetos/'.$tenantId; $dir=__DIR__.'/'.$rel;
    if(!is_dir($dir)&&!@mkdir($dir,0755,true)&&!is_dir($dir))throw new Exception('Não foi possível criar a pasta de PDFs.');
    try{$tok=bin2hex(random_bytes(8));}catch(Throwable $e){$tok=preg_replace('/[^a-zA-Z0-9]/','',uniqid('',true));}
    $nome='projeto_'.date('Ymd_His').'_'.$tok.'.pdf';
    if(!move_uploaded_file($tmp,$dir.'/'.$nome))throw new Exception('Não foi possível salvar o PDF.');
    return $rel.'/'.$nome;
}
function ap_del_pdf($rel){$rel=ltrim((string)$rel,'/');if(strpos($rel,'uploads/campanha/projetos/')!==0)return;$f=__DIR__.'/'.$rel;if(is_file($f))@unlink($f);}
function ap_tipo($v){$m=['projeto_lei'=>'Projeto de Lei','lei'=>'Lei','projeto_resolucao'=>'Projeto de Resolução','resolucao'=>'Resolução','indicacao'=>'Indicação','requerimento'=>'Requerimento','outro'=>'Outro'];return $m[$v]??'Documento';}

if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  $acao=$_POST['acao']??'salvar'; $tipo=$_POST['tipo']??'pauta';
  if($acao==='toggle_projeto'){
    $id=(int)($_POST['id']??0);$pdo->prepare("UPDATE campanha_projetos_leis SET ativo=IF(ativo=1,0,1) WHERE id=? AND tenant_id=?")->execute([$id,$tenantId]);
  } elseif($acao==='toggle_cadastro'){
    $id=(int)($_POST['id']??0);$pdo->prepare("UPDATE campanha_projetos_leis SET exigir_cadastro_download=IF(exigir_cadastro_download=1,0,1) WHERE id=? AND tenant_id=?")->execute([$id,$tenantId]);
  } elseif($acao==='excluir_projeto'){
    $id=(int)($_POST['id']??0);$q=$pdo->prepare("SELECT arquivo_pdf FROM campanha_projetos_leis WHERE id=? AND tenant_id=? LIMIT 1");$q->execute([$id,$tenantId]);$arq=$q->fetchColumn();
    $pdo->prepare("DELETE FROM campanha_projetos_leis WHERE id=? AND tenant_id=?")->execute([$id,$tenantId]); if($arq)ap_del_pdf($arq);
  } elseif($tipo==='realizacao'){
    $titulo=trim($_POST['titulo']??'');if($titulo==='')throw new Exception('Informe o título.');$img=campanha_upload('imagem','realizacoes');
    $pdo->prepare("INSERT INTO campanha_realizacoes (tenant_id,titulo,descricao,numero_destaque,imagem,ordem,ativo) VALUES (?,?,?,?,?,?,1)")->execute([$tenantId,$titulo,trim($_POST['descricao']??''),trim($_POST['numero_destaque']??''),$img,(int)($_POST['ordem']??0)]);
  } elseif($tipo==='projeto_lei'){
    $titulo=trim($_POST['titulo_projeto']??'');if($titulo==='')throw new Exception('Informe o título do projeto/lei.');
    $td=trim($_POST['tipo_documento']??'projeto_lei');$ok=['projeto_lei','lei','projeto_resolucao','resolucao','indicacao','requerimento','outro'];if(!in_array($td,$ok,true))$td='outro';
    $link=trim($_POST['link_integra']??'');if($link!==''&&!filter_var($link,FILTER_VALIDATE_URL))throw new Exception('Link externo inválido.');
    $pdf=ap_pdf('arquivo_pdf',$tenantId);
    $pdo->prepare("INSERT INTO campanha_projetos_leis (tenant_id,tipo,numero,ano,titulo,descricao,situacao,arquivo_pdf,link_integra,ordem,ativo,exigir_cadastro_download) VALUES (?,?,?,?,?,?,?,?,?,?,1,?)")
      ->execute([$tenantId,$td,trim($_POST['numero']??''),(int)($_POST['ano']??date('Y')),$titulo,trim($_POST['descricao_projeto']??''),trim($_POST['situacao']??''),$pdf,$link,(int)($_POST['ordem_projeto']??0),isset($_POST['exigir_cadastro_download'])?1:0]);
  } else {
    $titulo=trim($_POST['titulo']??'');if($titulo==='')throw new Exception('Informe o título.');
    $pdo->prepare("INSERT INTO campanha_pautas (tenant_id,titulo,descricao,icone,ordem,ativo) VALUES (?,?,?,?,?,1)")->execute([$tenantId,$titulo,trim($_POST['descricao']??''),trim($_POST['icone']??'fa-check'),(int)($_POST['ordem']??0)]);
  }
  header('Location: /admin_campanha_pautas?ok=1');exit;
 }catch(Throwable $e){$msg="<div class='alert alert-danger'>".ap_h($e->getMessage())."</div>";}
}
if(isset($_GET['delp'])){$pdo->prepare("DELETE FROM campanha_pautas WHERE id=? AND tenant_id=?")->execute([(int)$_GET['delp'],$tenantId]);header('Location: /admin_campanha_pautas');exit;}
if(isset($_GET['delr'])){$pdo->prepare("DELETE FROM campanha_realizacoes WHERE id=? AND tenant_id=?")->execute([(int)$_GET['delr'],$tenantId]);header('Location: /admin_campanha_pautas');exit;}
$s=$pdo->prepare("SELECT * FROM campanha_pautas WHERE tenant_id=? ORDER BY ordem,id");$s->execute([$tenantId]);$pautas=$s->fetchAll(PDO::FETCH_ASSOC);
$s=$pdo->prepare("SELECT * FROM campanha_realizacoes WHERE tenant_id=? ORDER BY ordem,id");$s->execute([$tenantId]);$real=$s->fetchAll(PDO::FETCH_ASSOC);
$s=$pdo->prepare("SELECT * FROM campanha_projetos_leis WHERE tenant_id=? ORDER BY ordem,ano DESC,id DESC");$s->execute([$tenantId]);$projetos=$s->fetchAll(PDO::FETCH_ASSOC);
?>
