<div class="tab-pane fade" id="projetos"><div class="row g-4"><div class="col-lg-5"><div class="card shadow-sm"><div class="card-body p-4"><h5>Novo Projeto / Lei</h5><form method="post" action="/admin_campanha_pautas" enctype="multipart/form-data"><input type="hidden" name="tipo" value="projeto_lei"><label class="form-label">Tipo</label><select name="tipo_documento" class="form-select mb-3"><option value="projeto_lei">Projeto de Lei</option><option value="lei">Lei</option><option value="projeto_resolucao">Projeto de Resolução</option><option value="resolucao">Resolução</option><option value="indicacao">Indicação</option><option value="requerimento">Requerimento</option><option value="outro">Outro</option></select><div class="row"><div class="col-7"><label class="form-label">Número</label><input name="numero" class="form-control mb-3" placeholder="Ex.: 123"></div><div class="col-5"><label class="form-label">Ano</label><input type="number" name="ano" value="<?=date('Y')?>" class="form-control mb-3"></div></div><label class="form-label">Título</label><input name="titulo_projeto" class="form-control mb-3" required><label class="form-label">Situação</label><select name="situacao" class="form-select mb-3"><option value="">Selecione</option><option>Apresentado</option><option>Em tramitação</option><option>Aprovado</option><option>Sancionado</option><option>Transformado em lei</option><option>Arquivado</option><option>Rejeitado</option></select><label class="form-label">Resumo / descrição</label><textarea name="descricao_projeto" rows="4" class="form-control mb-3"></textarea><label class="form-label fw-bold">PDF da íntegra</label><input type="file" name="arquivo_pdf" accept=".pdf,application/pdf" class="form-control mb-2"><div class="small text-muted mb-3">Máximo 15 MB.</div><label class="form-label">Link externo (opcional)</label><input type="url" name="link_integra" class="form-control mb-3" placeholder="https://..."><div class="form-check form-switch mb-3"><input class="form-check-input" type="checkbox" name="exigir_cadastro_download" value="1" id="cad"><label class="form-check-label fw-bold" for="cad">Exigir cadastro para baixar o PDF</label><div class="small text-muted">Quando ativado, o visitante informa os dados uma vez e depois é reconhecido pelo site.</div></div><label class="form-label">Ordem</label><input type="number" name="ordem_projeto" value="0" class="form-control mb-3"><button class="btn btn-primary pill px-4">Salvar projeto</button></form></div></div></div>
<div class="col-lg-7"><div class="card shadow-sm"><div class="card-body p-4"><div class="d-flex justify-content-between"><h5>Projetos e Leis</h5><span class="badge bg-primary"><?=count($projetos)?></span></div><?php if(!$projetos):?><div class="text-muted">Nenhum documento cadastrado.</div><?php endif;?><?php foreach($projetos as $pr):?><div class="item mb-3"><div class="d-flex justify-content-between gap-3"><div class="flex-grow-1"><div class="mb-2"><span class="badge text-bg-light border"><?=ap_h(ap_tipo($pr['tipo']))?></span> <span class="badge <?=((int)$pr['ativo']===1?'bg-success':'bg-secondary')?>"><?=((int)$pr['ativo']===1?'Ativo':'Inativo')?></span> <?php if((int)($pr['exigir_cadastro_download']??0)===1):?><span class="badge bg-warning text-dark">Cadastro obrigatório</span><?php else:?><span class="badge bg-light text-dark border">Download livre</span><?php endif;?></div><strong><?=ap_h(ap_tipo($pr['tipo']))?> <?=ap_h($pr['numero'])?><?=!empty($pr['ano'])?'/'.(int)$pr['ano']:''?> — <?=ap_h($pr['titulo'])?></strong><?php if(!empty($pr['descricao'])):?><div class="small text-muted mt-1"><?=nl2br(ap_h($pr['descricao']))?></div><?php endif;?><div class="mt-2"><?php if(!empty($pr['arquivo_pdf'])):?><span class="small text-success"><i class="fa-solid fa-file-pdf"></i> PDF enviado</span><?php else:?><span class="small text-muted">Sem PDF</span><?php endif;?></div></div></div><div class="d-flex flex-wrap gap-2 mt-3"><form method="post" action="/admin_campanha_pautas"><input type="hidden" name="acao" value="toggle_projeto"><input type="hidden" name="id" value="<?=(int)$pr['id']?>"><button class="btn btn-sm <?=((int)$pr['ativo']===1?'btn-outline-secondary':'btn-outline-success')?>"><?=((int)$pr['ativo']===1?'Desativar':'Ativar')?></button></form><form method="post" action="/admin_campanha_pautas"><input type="hidden" name="acao" value="toggle_cadastro"><input type="hidden" name="id" value="<?=(int)$pr['id']?>"><button class="btn btn-sm btn-outline-warning"><?=((int)($pr['exigir_cadastro_download']??0)===1?'Liberar sem cadastro':'Exigir cadastro')?></button></form><form method="post" action="/admin_campanha_pautas" onsubmit="return confirm('Excluir este documento e o PDF associado?')"><input type="hidden" name="acao" value="excluir_projeto"><input type="hidden" name="id" value="<?=(int)$pr['id']?>"><button class="btn btn-sm btn-outline-danger">Excluir</button></form></div></div><?php endforeach;?></div></div></div></div></div>
